using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or the OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = new ResearchTools();

var agent = new ChatClientAgent(chatClient, new ChatClientAgentOptions
{
    Instructions = """
        You are a research agent. When given a topic, you:
        1. Search the web for relevant information using the web_search tool.
        2. Take notes on key findings using the take_note tool.
        3. Perform additional searches to fill gaps.
        4. Once you have enough information, produce a final summary.
        Be thorough but concise. Always cite your sources.
        """,
    Tools = [AIFunctionFactory.Create(tools.WebSearch), AIFunctionFactory.Create(tools.TakeNote)],
    MaximumIterations = 10,
});

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new AgentInvokeOptions { MaximumIterations = 10 };

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Notes ===");
foreach (var note in tools.Notes)
{
    Console.WriteLine($"- {note}");
}

/// <summary>
/// Tools available to the research agent.
/// </summary>
sealed class ResearchTools
{
    private readonly HttpClient _httpClient = new();
    private readonly List<string> _notes = [];

    public IReadOnlyList<string> Notes => _notes;

    [Description("Searches the web for information on a given query. Returns search result snippets.")]
    public async Task<string> WebSearch([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Searching: {query}]");

        try
        {
            // Uses a public search API (DuckDuckGo Instant Answer)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await _httpClient.GetStringAsync(url);

            using var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract text
            var abstractText = root.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrEmpty(abstractText))
            {
                var source = root.GetProperty("AbstractSource").GetString();
                results.Add($"[{source}] {abstractText}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrEmpty(text))
                    {
                        results.Add(text);
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try a more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Takes a research note to remember a key finding. Use this to track important facts.")]
    public string TakeNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Note saved: {note[..Math.Min(note.Length, 60)]}...]");
        return $"Note saved. You have {_notes.Count} note(s) total.";
    }
}

