using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// Create IChatClient from OpenAI SDK via MEAI abstraction
var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient();

// Define tools
var tools = new ResearchTools();
var aiTools = new AITool[]
{
    AIFunctionFactory.Create(tools.WebSearch),
    AIFunctionFactory.Create(tools.TakeNote),
};

// Build the agent with Microsoft Agent Framework
var agent = chatClient.AsAIAgent(
    instructions: """
        You are a research agent. When given a topic, you:
        1. Search the web for relevant information using the WebSearch tool.
        2. Take notes on key findings using the TakeNote tool.
        3. Perform additional searches to fill knowledge gaps.
        4. Once you have enough information, produce a final comprehensive summary.
        Be thorough but concise. Always cite your sources.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: aiTools);

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

