// Create IChatClient from OpenAI SDK via MEAI abstraction
var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient();

// Define tools
var tools = new ResearchTools();
var aiTools = new AITool[]
{
    AIFunctionFactory.Create(tools.WebSearch),
    AIFunctionFactory.Create(tools.TakeNote),
};

// Build the agent with Microsoft Agent Framework
var agent = chatClient.AsAIAgent(
    instructions: """
        You are a research agent. When given a topic, you:
        1. Search the web for relevant information using the WebSearch tool.
        2. Take notes on key findings using the TakeNote tool.
        3. Perform additional searches to fill knowledge gaps.
        4. Once you have enough information, produce a final comprehensive summary.
        Be thorough but concise. Always cite your sources.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: aiTools);

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

using var cts = new CancellationTokenSource(TimeSpan.FromMinutes(2));
var session = await agent.CreateSessionAsync(cancellationToken: cts.Token);

var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions,
    cts.Token))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine("\n\n=== Research Notes ===");
if (tools.Notes.Count == 0)
{
    Console.WriteLine("  (no notes taken)");
}
else
{
    foreach (var note in tools.Notes)
    {
        Console.WriteLine($"  • {note}");
    }
}

/// <summary>Tools available to the research agent.</summary>
sealed class ResearchTools
{
    private readonly HttpClient _httpClient = new();
    private readonly List<string> _notes = [];

    public IReadOnlyList<string> Notes => _notes;

    [Description("Searches the web for information on a given query. Returns search result snippets.")]
    public async Task<string> WebSearch([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Searching: \"{query}\"]");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await _httpClient.GetStringAsync(url);

            using var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            var abstractText = root.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrEmpty(abstractText))
            {
                var source = root.GetProperty("AbstractSource").GetString();
                results.Add($"[{source}] {abstractText}");
            }

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrEmpty(text))
                    {
                        results.Add(text);
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try a more specific or different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Takes a research note to remember a key finding. Use this to track important facts discovered during research.")]
    public string TakeNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        var preview = note.Length > 60 ? note[..60] + "..." : note;
        Console.WriteLine($"  [Note #{_notes.Count} saved: {preview}]");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }
}

